        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    pressure = max(highest_prev, rich_pressure)

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        emergency = max(DAILY_SALARY * 1.15, pressure + 3.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.95, pressure + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.8, avg_prev + 2.0)
        return float(min(budget, bid))

    if tight_supply:
        if pressure >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.22
        else:
            bid = max(DAILY_SALARY * 0.62, avg_prev * 0.72)
    elif ample_supply:
        if pressure >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.18
        else:
            bid = DAILY_SALARY * 0.42
    else:
        if pressure >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.25
        else:
            bid = max(DAILY_SALARY * 0.5, avg_prev * 0.6)

    if day >= 8 and hp >= 6:
        bid *= 0.9

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        # previous_trace fields include 'bid'
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate opponent pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Conservative baseline: aim to secure enough water for survival
    # If supply is near max, we can bid less; if near min, bid more.
    # Normalize supply to [0,1]
    if MAX_SUPPLY != MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5

    # Need roughly ceil(WATER_REQ / supply) days? Here supply is total water, bids compete for share.
    # Use hp to decide risk tolerance.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we are in danger, prioritize survival with a high bid.
    if hp <= 2.0 or no_water_days >= 2:
        target = DAILY_SALARY * 0.95
    elif hp <= 4.0:
        target = DAILY_SALARY * 0.75
    else:
        # When supply is low, bid more to avoid losing allocation.
        # supply_norm=0 => low supply => higher bid
        target = DAILY_SALARY * (0.62 + (1.0 - supply_norm) * 0.18)

    # Exploit yesterday: Eric/Alex survived with high bids; match just below their pressure.
    # We don't know their current bids, so we anchor to highest_prev_bid.
    if highest_prev_bid > 0:
        # If opponents were bidding very high, increase our target but try to undercut.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, min(budget, highest_prev_bid * 0.92))
        else:
            # Otherwise, bid enough to be competitive: slightly above second-highest
            if second_prev_bid > 0:
                target = max(target, min(budget, second_prev_bid * 1.03))

    # Cap by budget and ensure non-negative
    if budget <= 0:
        return 0.0

    bid = float(target)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # Small final adjustment: if supply is very low, add a bit; if very high, subtract a bit.
    if supply <= MIN_SUPPLY + 1.0:
        bid = min(budget, bid * 1.06)
    elif supply >= MAX_SUPPLY - 1.0:
        bid = max(0.0, bid * 0.95)

    # Keep bid integral-ish for stability
    return float(int(bid))

