    DAILY_SALARY = 80
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        # No competition: bid minimal to get water if needed
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.6)
        return 0.0

    # Extract yesterday's bids from opponents' previous_trace
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Estimate required bid based on yesterday's max
    if prev_bids:
        max_prev_bid = max(prev_bids)
    else:
        max_prev_bid = DAILY_SALARY * 1.2  # fallback estimate

    # Base decision on hp and supply
    if hp <= 2:
        # Critical need: bid high but not exceed budget
        target_bid = min(budget, max(DAILY_SALARY * 0.95, max_prev_bid * 0.9))
    elif hp <= 5:
        # Moderate need: bid enough to stay competitive
        target_bid = min(budget, max(DAILY_SALARY * 0.65, max_prev_bid * 0.7))
    else:
        # Healthy: conserve money, bid low
        target_bid = min(budget, max(DAILY_SALARY * 0.25, max_prev_bid * 0.4))

    # Adjust for supply: higher supply means more water available, lower bids suffice
    supply_factor = (supply - 15) / 10.0  # 0.0 to 1.0
    adjusted_bid = target_bid * (1.0 - 0.3 * supply_factor)

    # Ensure bid is within realistic range and my budget, and ensure no float index issues
    final_bid = max(0.0, min(budget, adjusted_bid))
    return final_bid

